# Schema SDL
type User {
  id: ID!
  email: String!
  displayName: String
  role: UserRole!
  posts: [Post!]!
  createdAt: DateTime!
}

enum UserRole {
  ADMIN
  EDITOR
  VIEWER
}

type Post {
  id: ID!
  title: String!
  body: String!
  author: User!
  status: PostStatus!
  publishedAt: DateTime
}

enum PostStatus {
  DRAFT
  PUBLISHED
  ARCHIVED
}

type Query {
  user(id: ID!): User
  users(filter: UserFilter, limit: Int = 20): [User!]!
}

input UserFilter {
  role: UserRole
  searchTerm: String
}

type Mutation {
  createPost(input: CreatePostInput!): Post!
  publishPost(postId: ID!): Post!
}

input CreatePostInput {
  title: String!
  body: String!
}

scalar DateTime

