// Resolver map đầy đủ
const resolvers = {
  Query: {
    // parent = {} (root), args = { id }, context = { db, currentUser }
    user: async (parent, { id }, context, info) => {
      // Kiểm tra auth từ context
      if (!context.currentUser) throw new AuthenticationError('Login required');
      return context.db.users.findById(id);
    },
  },

  User: {
    // parent = User object từ Query.user resolver
    // Resolver này được gọi cho mỗi User trong kết quả
    posts: async (parent, args, context) => {
      // parent.id = userId của User đang resolve
      return context.db.posts.findByUserId(parent.id);
    },

    // Default resolver — không cần viết vì User object đã có .email property
    // email: (parent) => parent.email,  // implicit

    // Custom field name mapping
    displayName: (parent) => `${parent.firstName} ${parent.lastName}`,
  },

  Mutation: {
    createPost: async (parent, { input }, { db, currentUser }) => {
      if (!currentUser) throw new AuthenticationError('Login required');
      return db.posts.create({
        ...input,
        authorId: currentUser.id,
        status: 'DRAFT',
      });
    },
  },
};

