# Named fragment — reusable
fragment UserCard on User {
  id
  displayName
  avatarUrl
  role
}

fragment PostPreview on Post {
  id
  title
  excerpt
  publishedAt
  author { ...UserCard }  # Nested fragment spread
}

# Reuse fragments
query GetFeed {
  feedPosts {
    ...PostPreview
  }
}

query GetUserProfile($userId: ID!) {
  user(id: $userId) {
    ...UserCard
    bio
    followerCount
    recentPosts { ...PostPreview }
  }
}

# Inline fragment — Union/Interface type discrimination
query GetSearchResults($query: String!) {
  search(query: $query) {
    # SearchResult = Post | User | Tag (Union type)
    ... on Post {
      id
      title
      author { ...UserCard }
    }
    ... on User {
      ...UserCard
      followerCount
    }
    ... on Tag {
      id
      name
      postCount
    }
  }
}

