import DataLoader from 'dataloader';
import { PrismaClient } from '@prisma/client';

// ✅ Tạo DataLoaders trong context factory (per-request scope)
export function createContext(prisma: PrismaClient) {
  // Batch function: nhận [userId1, userId2, ...] → trả [User1, User2, ...]
  const userLoader = new DataLoader<string, User>(async (userIds) => {
    const users = await prisma.user.findMany({
      where: { id: { in: [...userIds] } },
    });

    // QUAN TRỌNG: kết quả phải cùng thứ tự và length với input keys
    const userMap = new Map(users.map((u) => [u.id, u]));
    return userIds.map((id) => userMap.get(id) ?? new Error(`User ${id} not found`));
  });

  const postsByAuthorLoader = new DataLoader<string, Post[]>(async (authorIds) => {
    const posts = await prisma.post.findMany({
      where: { authorId: { in: [...authorIds] } },
    });
    // Group by authorId
    const grouped = new Map<string, Post[]>();
    authorIds.forEach((id) => grouped.set(id, []));
    posts.forEach((p) => grouped.get(p.authorId)?.push(p));
    return authorIds.map((id) => grouped.get(id) ?? []);
  });

  return { prisma, userLoader, postsByAuthorLoader, currentUser: null };
}

// Resolver dùng DataLoader
const resolvers = {
  Post: {
    // TRƯỚC (N+1): 1 query/post
    // author: (post) => prisma.user.findUnique({ where: { id: post.authorId } }),

    // SAU (batched): tất cả posts share 1 query batch
    author: (post, _args, { userLoader }) => userLoader.load(post.authorId),
    tags: (post, _args, { tagsByPostLoader }) => tagsByPostLoader.load(post.id),
  },
};

