import { ApolloServer } from '@apollo/server';
import depthLimit from 'graphql-depth-limit';
import { createComplexityLimitRule } from 'graphql-query-complexity';

// Complexity estimator
const complexityRule = createComplexityLimitRule(1000, {
  onCost: (cost) => console.log('Query cost:', cost),
  createError: (max, actual) =>
    new Error(`Query too complex: ${actual}. Max allowed: ${max}`),
  estimators: [
    // List fields cost = limit arg × child complexity
    fieldExtensionsEstimator(),
    simpleEstimator({ defaultComplexity: 1 }),
  ],
});

const server = new ApolloServer({
  typeDefs,
  resolvers,
  validationRules: [
    depthLimit(7),   // Max 7 levels nesting
    complexityRule,  // Max cost 1000
  ],
  introspection: process.env.NODE_ENV !== 'production', // Disable introspection in prod
});

