import depthLimit from 'graphql-depth-limit';
import { createComplexityLimitRule, simpleEstimator } from 'graphql-query-complexity';

const complexityRule = createComplexityLimitRule(1000, {
  onCost: (cost) => console.log(`Query cost: ${cost}`),
  createError: (max, actual) =>
    new GraphQLError(`Query too complex: ${actual} (max: ${max})`, {
      extensions: { code: 'QUERY_TOO_COMPLEX' },
    }),
  estimators: [
    simpleEstimator({ defaultComplexity: 1 }),
  ],
});

const server = new ApolloServer({
  schema,
  validationRules: [
    depthLimit(6),   // Max 6 levels nesting
    complexityRule,
  ],
  introspection: process.env.NODE_ENV !== 'production',
  plugins: [
    // Timeout slow operations
    {
      async requestDidStart() {
        return {
          async executionDidStart() {
            const timeout = setTimeout(() => {
              throw new Error('Query timeout');
            }, 5000); // 5s timeout
            return { async executionDidEnd() { clearTimeout(timeout); } };
          },
        };
      },
    },
  ],
});

