// Pattern 1: Standard GraphQL errors với extensions
const resolvers = {
  Query: {
    user: async (_, { id }, { db, currentUser }) => {
      if (!currentUser) {
        throw new GraphQLError('Authentication required', {
          extensions: { code: 'UNAUTHENTICATED', http: { status: 401 } },
        });
      }
      const user = await db.users.findById(id);
      if (!user) {
        throw new GraphQLError(`User ${id} not found`, {
          extensions: { code: 'NOT_FOUND' },
        });
      }
      return user;
    },
  },
  User: {
    // posts resolver fail → partial error (user data returned, posts = null + error)
    posts: async (user, _, { db }) => {
      return db.posts.findByAuthorId(user.id);
    },
  },
};

// Pattern 2: Union error types (schema-first approach)
// schema:
// union CreatePostResult = Post | ValidationError | AuthError
// type ValidationError { field: String! message: String! }
// type Mutation { createPost(input: Input!): CreatePostResult! }

// resolver:
const mutationResolvers = {
  Mutation: {
    createPost: async (_, { input }, { currentUser, db }) => {
      if (!currentUser) {
        return { __typename: 'AuthError', message: 'Not authenticated' };
      }
      if (!input.title?.trim()) {
        return { __typename: 'ValidationError', field: 'title', message: 'Required' };
      }
      const post = await db.posts.create({ ...input, authorId: currentUser.id });
      return { __typename: 'Post', ...post };
    },
  },
};

