// Apollo Server với response cache
import { ApolloServer } from '@apollo/server';
import { ApolloServerPluginCacheControl } from '@apollo/server/plugin/cacheControl';
import responseCachePlugin from '@apollo/server-plugin-response-cache';
import { createRedisCache } from '@apollo/utils.keyvadapter';
import Redis from 'ioredis';

const redis = new Redis(process.env.REDIS_URL);

const server = new ApolloServer({
  schema,
  plugins: [
    ApolloServerPluginCacheControl({ defaultMaxAge: 0 }),
    responseCachePlugin({
      cache: createRedisCache(redis),  // Dùng Redis thay vì in-memory
      sessionId: (requestContext) =>
        requestContext.contextValue.currentUser?.id ?? null, // Separate public vs private
    }),
  ],
});

// Schema: set cache hints per type/field
const typeDefs = gql`
  type Product @cacheControl(maxAge: 300) {  # 5 min public cache
    id: ID!
    name: String!
    price: Float!
    stock: Int @cacheControl(maxAge: 30)    # Stock freshness quan trọng hơn
  }

  type Order @cacheControl(maxAge: 0, scope: PRIVATE) {  # Không cache order
    id: ID!
    userId: ID!
    totalAmount: Float!
  }

  type Query {
    product(id: ID!): Product @cacheControl(maxAge: 300)
    myOrders: [Order!]! @cacheControl(scope: PRIVATE)
  }
`;

