// context factory — xác thực JWT, set currentUser
export async function createContext({ req }: { req: Request }) {
  const authHeader = req.headers.authorization ?? '';
  let currentUser: User | null = null;

  if (authHeader.startsWith('Bearer ')) {
    const token = authHeader.slice(7);
    try {
      const payload = jwt.verify(token, process.env.JWT_SECRET!) as JwtPayload;
      currentUser = await prisma.user.findUnique({ where: { id: payload.sub } });
    } catch {
      // Invalid token — currentUser remains null (allow public queries)
    }
  }

  return { prisma, currentUser };
}

// Custom @auth directive transformer
function authDirectiveTransformer(schema: GraphQLSchema) {
  return mapSchema(schema, {
    [MapperKind.OBJECT_FIELD]: (fieldConfig) => {
      const authDirective = getDirective(schema, fieldConfig, 'auth')?.[0];
      if (!authDirective) return fieldConfig;

      const { requires } = authDirective;
      const originalResolve = fieldConfig.resolve ?? defaultFieldResolver;

      return {
        ...fieldConfig,
        resolve: async (source, args, context, info) => {
          if (!context.currentUser) {
            throw new GraphQLError('Authentication required', {
              extensions: { code: 'UNAUTHENTICATED' },
            });
          }
          if (requires && context.currentUser.role !== requires) {
            throw new GraphQLError('Insufficient permissions', {
              extensions: { code: 'FORBIDDEN' },
            });
          }
          return originalResolve(source, args, context, info);
        },
      };
    },
  });
}

