# Connection spec schema
type UserConnection {
  edges: [UserEdge!]!
  pageInfo: PageInfo!
  totalCount: Int!
}

type UserEdge {
  node: User!
  cursor: String!
}

type PageInfo {
  hasNextPage: Boolean!
  hasPreviousPage: Boolean!
  startCursor: String
  endCursor: String
}

type Query {
  users(first: Int, after: String, last: Int, before: String, filter: UserFilter): UserConnection!
}

---
// TypeScript resolver implementation
import { encode, decode } from 'base64url';

const resolvers = {
  Query: {
    users: async (_, { first = 20, after }, { db }) => {
      const cursorId = after ? decode(after) : null;

      const users = await db.query(
        `SELECT * FROM users
         WHERE ($1::uuid IS NULL OR id > $1::uuid)
         ORDER BY id ASC
         LIMIT $2`,
        [cursorId, first + 1],  // Fetch +1 để check hasNextPage
      );

      const hasNextPage = users.length > first;
      const items = hasNextPage ? users.slice(0, first) : users;
      const totalCount = await db.query('SELECT COUNT(*) FROM users');

      return {
        edges: items.map((user) => ({
          node: user,
          cursor: encode(user.id),  // Opaque cursor
        })),
        pageInfo: {
          hasNextPage,
          hasPreviousPage: !!after,
          startCursor: items[0] ? encode(items[0].id) : null,
          endCursor: items.at(-1) ? encode(items.at(-1)!.id) : null,
        },
        totalCount: parseInt(totalCount.rows[0].count),
      };
    },
  },
};

