// Redis PubSub — works with multiple server instances
const pubsub = new RedisPubSub({
  publisher: new Redis(process.env.REDIS_URL),
  subscriber: new Redis(process.env.REDIS_URL),  // Separate connections
});

const ORDER_UPDATED = 'ORDER_UPDATED';

const resolvers = {
  Subscription: {
    orderUpdated: {
      // Filter: chỉ send event của order thuộc về subscriber
      subscribe: withFilter(
        () => pubsub.asyncIterator([ORDER_UPDATED]),
        (payload, variables, context) => {
          // payload.orderUpdated.userId === context.currentUser.id
          return payload.orderUpdated.userId === context.currentUser?.id;
        },
      ),
    },
  },
