    updateOrderStatus: async (_, { orderId, status }, { db }) => {
      const order = await db.orders.update(orderId, { status });
      // Publish event — all Redis subscribers receive this
      await pubsub.publish(ORDER_UPDATED, { orderUpdated: order });
      return order;
    },
  },
};

