import { ApolloServerPlugin } from '@apollo/server';
import { trace, SpanStatusCode, context, propagation } from '@opentelemetry/api';

const graphqlTracingPlugin: ApolloServerPlugin = {
  async requestDidStart(requestContext) {
    const tracer = trace.getTracer('graphql');
    const requestSpan = tracer.startSpan(`graphql.request`);

    return {
      async didResolveOperation({ operationName }) {
        requestSpan.setAttribute('graphql.operation.name', operationName ?? 'anonymous');
        requestSpan.setAttribute('graphql.operation.type',
          requestContext.operation?.operation ?? 'unknown');
      },

      async executionDidStart() {
        return {
          willResolveField({ info }) {
            const fieldSpan = tracer.startSpan(
              `graphql.resolve.${info.parentType.name}.${info.fieldName}`,
              { parent: requestSpan }
            );
            return (error) => {
              if (error) {
                fieldSpan.setStatus({ code: SpanStatusCode.ERROR, message: error.message });
              }
              fieldSpan.end();
            };
          },
        };
      },

      async willSendResponse({ response }) {
        const hasErrors = response.body.kind === 'single'
          && response.body.singleResult.errors?.length;
        if (hasErrors) {
          requestSpan.setStatus({ code: SpanStatusCode.ERROR });
        }
        requestSpan.end();
        // Send metrics to Prometheus
        graphqlOperationDuration
          .labels({ operation: requestContext.operationName ?? 'anonymous' })
          .observe(Date.now() - requestContext.request.http!.headers.get('x-request-start')!);
      },
    };
  },
};

