// Approach 1: Scoped Prisma Client per-request
// Tạo Prisma client với user scope cho mỗi request
function createScopedPrisma(userId: string, basePrisma: PrismaClient) {
  return basePrisma.$extends({
    query: {
      // Scope tất cả findMany queries theo userId
      order: {
        async findMany({ args, query }) {
          // Inject user filter — client không thể bypass
          args.where = { ...args.where, userId };
          return query(args);
        },
        async findUnique({ args, query }) {
          const result = await query(args);
          // Post-query ownership check
          if (result && result.userId !== userId) {
            throw new GraphQLError('Order not found', {
              extensions: { code: 'NOT_FOUND' },
            });
          }
          return result;
        },
      },
    },
  });
}

// Context factory: inject scoped DB
export async function createContext({ req }) {
  const currentUser = await authenticateRequest(req);
  const scopedPrisma = currentUser
    ? createScopedPrisma(currentUser.id, prisma)
    : null;
  return { currentUser, db: scopedPrisma ?? prisma };
}

// Resolver: chỉ dùng context.db — tự động scoped
const resolvers = {
  Query: {
    myOrders: (_, __, { db, currentUser }) => {
      if (!currentUser) throw new GraphQLError('Not authenticated');
      // db.order.findMany tự inject userId filter
      return db.order.findMany({ orderBy: { createdAt: 'desc' } });
    },
  },
};

