# Pattern 1: Direct return (NOT recommended)
type Mutation {
  createPost(input: CreatePostInput!): Post!  # Forced to throw on error
}

# Pattern 2: Payload type (Shopify pattern — flexible)
type CreatePostPayload {
  post: Post                    # Null if error
  userErrors: [UserError!]!    # Empty if success
  correlationId: String!       # For client tracking
}

type UserError {
  field: [String!]  # Which field caused error
  message: String!
  code: ErrorCode!
}

enum ErrorCode {
  VALIDATION_FAILED
  NOT_FOUND
  FORBIDDEN
  DUPLICATE
}

# Pattern 3: Union type (type-safe, discoverable)
union CreatePostResult =
  Post
  | ValidationError
  | AuthorizationError
  | DuplicatePostError

type Mutation {
  createPost(input: CreatePostInput!): CreatePostResult!
}

---
// Resolver — Pattern 2 (Payload)
const mutationResolvers = {
  Mutation: {
    createPost: async (_, { input }, { db, currentUser }) => {
      // Validation
      const errors = validateCreatePostInput(input);
      if (errors.length > 0) {
        return {
          post: null,
          userErrors: errors,
          correlationId: crypto.randomUUID(),
        };
      }
      // Create
      const post = await db.posts.create({ ...input, authorId: currentUser.id });
      return { post, userErrors: [], correlationId: crypto.randomUUID() };
    },
  },
};

// Client usage — Payload pattern
const CREATE_POST = gql`
  mutation CreatePost($input: CreatePostInput!) {
    createPost(input: $input) {
      post { id title }
      userErrors { field message code }
      correlationId
    }
  }
`;
// Check: if (result.data.createPost.userErrors.length === 0) { success }

