import { GraphQLScalarType, GraphQLError, Kind } from 'graphql';

// Custom DateTime scalar
export const DateTimeScalar = new GraphQLScalarType({
  name: 'DateTime',
  description: 'ISO 8601 datetime string',

  // JS → JSON (response serialization)
  serialize(value) {
    if (value instanceof Date) {
      if (isNaN(value.getTime())) {
        throw new GraphQLError('Invalid Date object');
      }
      return value.toISOString();
    }
    if (typeof value === 'string') {
      const date = new Date(value);
      if (isNaN(date.getTime())) throw new GraphQLError(`Invalid date string: ${value}`);
      return date.toISOString();
    }
    throw new GraphQLError(`Cannot serialize DateTime: ${value}`);
  },

  // JSON variable → JS (input coercion from variable)
  parseValue(value) {
    if (typeof value !== 'string') throw new GraphQLError('DateTime must be a string');
    const date = new Date(value);
    if (isNaN(date.getTime())) throw new GraphQLError(`Invalid DateTime: ${value}`);
    return date;
  },

  // Literal in query → JS (hardcoded argument)
  parseLiteral(ast) {
    if (ast.kind !== Kind.STRING) {
      throw new GraphQLError('DateTime literal must be a string');
    }
    const date = new Date(ast.value);
    if (isNaN(date.getTime())) throw new GraphQLError(`Invalid DateTime: ${ast.value}`);
    return date;
  },
});

