import { ApolloClient, InMemoryCache } from '@apollo/client';
import { BatchHttpLink } from '@apollo/client/link/batch-http';
import { RetryLink } from '@apollo/client/link/retry';

const batchLink = new BatchHttpLink({
  uri: '/graphql',
  batchMax: 10,      // Max 10 operations per batch
  batchInterval: 20, // Wait 20ms to collect operations
});

const client = new ApolloClient({
  link: new RetryLink().concat(batchLink),
  cache: new InMemoryCache(),
});

// Fragment colocation — component declares its own data needs
// UserCard.tsx
const USER_CARD_FRAGMENT = gql`
  fragment UserCard on User {
    id
    displayName
    avatarUrl
    role
  }
`;

export function UserCard({ user }: { user: UserCardFragment }) {
  return <div>{user.displayName}</div>;
}
UserCard.fragment = USER_CARD_FRAGMENT;

// Parent query — composes all fragments
const GET_POST = gql`
  query GetPost($postId: ID!) {
    post(id: $postId) {
      id
      title
      body
      author {
        ...UserCard  # Include UserCard's data needs
      }
    }
  }
  ${UserCard.fragment}  # Spread fragment definition
`;

// Single query fetch for entire page — zero waterfalls

