import { parse, visit, print, Kind } from 'graphql';
import type { DocumentNode, FieldNode, ObjectValueNode } from 'graphql';

// Transform: auto-inject tenantId into specific queries
function injectTenantFilter(
  query: DocumentNode,
  tenantId: string
): DocumentNode {
  return visit(query, {
    // Visit every Field node
    Field: {
      enter(node: FieldNode) {
        // Inject filter argument on root-level list queries
        if (node.name.value === 'orders' || node.name.value === 'products') {
          const tenantArg = {
            kind: Kind.ARGUMENT,
            name: { kind: Kind.NAME, value: 'tenantId' },
            value: {
              kind: Kind.STRING,
              value: tenantId,
              block: false,
            },
          };

          return {
            ...node,
            arguments: [
              ...(node.arguments ?? []),
              tenantArg,
            ],
          };
        }
      },
    },
  });
}

// Usage
const originalQuery = parse(`
  query GetOrders {
    orders { id status totalAmount }
  }
`);

const tenantQuery = injectTenantFilter(originalQuery, 'tenant-abc-123');
console.log(print(tenantQuery));
// Output:
// query GetOrders {
//   orders(tenantId: "tenant-abc-123") { id status totalAmount }
// }

// Complexity analyzer using AST visit
function calculateQueryComplexity(document: DocumentNode): number {
  let complexity = 0;
  visit(document, {
    Field: {
      enter(node) {
        complexity += 1;
        // List fields add more complexity
        if (node.name.value.endsWith('s') || node.arguments?.some(
          (a) => a.name.value === 'first' || a.name.value === 'limit'
        )) {
          complexity += 5;
        }
      },
    },
  });
  return complexity;
}

