import { RateLimiterRedis } from 'rate-limiter-flexible';
import Redis from 'ioredis';
import { getComplexity, simpleEstimator } from 'graphql-query-complexity';

const redis = new Redis(process.env.REDIS_URL);

// Two-tier rate limiting
const requestLimiter = new RateLimiterRedis({
  storeClient: redis,
  keyPrefix: 'rl:req',
  points: 100,    // 100 requests
  duration: 60,   // per minute per user
});

const costLimiter = new RateLimiterRedis({
  storeClient: redis,
  keyPrefix: 'rl:cost',
  points: 5000,   // 5000 complexity points
  duration: 60,   // per minute per user
});

// Middleware: check rate limits before execution
export const rateLimitPlugin: ApolloServerPlugin = {
  async requestDidStart() {
    return {
      async executionDidStart({ operationName, document, contextValue }) {
        const userId = contextValue.currentUser?.id ?? contextValue.ip;

        // 1. Request rate limit
        try {
          await requestLimiter.consume(userId);
        } catch {
          throw new GraphQLError('Too many requests. Slow down!', {
            extensions: { code: 'RATE_LIMITED', retryAfter: 60 },
          });
        }

        // 2. Cost-based rate limit
        const queryCost = getComplexity({
          schema,
          query: document,
          estimators: [simpleEstimator({ defaultComplexity: 1 })],
        });

        try {
          await costLimiter.consume(userId, queryCost);
        } catch (rateLimiterRes: any) {
          throw new GraphQLError(
            `Query too expensive. Budget exceeded. Retry after ${Math.ceil(rateLimiterRes.msBeforeNext / 1000)}s`,
            {
              extensions: {
                code: 'COST_LIMIT_EXCEEDED',
                queryCost,
                retryAfter: Math.ceil(rateLimiterRes.msBeforeNext / 1000),
              },
            },
          );
        }
      },
    };
  },
};

