import { stitchSchemas } from '@graphql-tools/stitch';
import { wrapSchema, FilterRootFields, RenameTypes } from '@graphql-tools/wrap';
import { buildHTTPExecutor } from '@graphql-tools/executor-http';

// Stitch internal schema + third-party GitHub API
async function buildGatewaySchema() {
  // Internal schema
  const internalSchema = makeExecutableSchema({
    typeDefs: internalTypeDefs,
    resolvers: internalResolvers,
  });

  // Remote GitHub GraphQL API
  const githubExecutor = buildHTTPExecutor({
    endpoint: 'https://api.github.com/graphql',
    headers: { Authorization: `bearer ${process.env.GITHUB_TOKEN}` },
  });

  const githubSchema = await schemaFromExecutor(githubExecutor);

  // Wrap + transform GitHub schema
  const wrappedGithubSchema = wrapSchema({
    schema: githubSchema,
    executor: githubExecutor,
    transforms: [
      // Only expose subset of GitHub API
      new FilterRootFields(
        (operation, fieldName) =>
          operation === 'Query' && ['repository', 'user'].includes(fieldName)
      ),
      // Prefix types to avoid conflicts
      new RenameTypes((typeName) => `GitHub_${typeName}`),
    ],
  });

  return stitchSchemas({
    subschemas: [
      { schema: internalSchema },
      { schema: wrappedGithubSchema },
    ],
    // Type merging: link GitHub User to internal User by login
    typeMergingOptions: {
      typeCandidates: {
        User: {
          // Internal User.githubLogin → GitHub User.login
          fieldName: 'githubUser',
          selectionSet: '{ githubLogin }',
          args: (partial) => ({ login: partial.githubLogin }),
        },
      },
    },
  });
}

