import {
  ApolloServerPluginLandingPageLocalDefault,
  ApolloServerPluginLandingPageProductionDefault,
  ApolloServerPluginLandingPageDisabled,
} from '@apollo/server/plugin/landingPage';

const isProduction = process.env.NODE_ENV === 'production';

const server = new ApolloServer({
  schema,
  introspection: !isProduction,  // Disable introspection in prod
  plugins: [
    isProduction
      ? // Option 1: Disable entirely
        // ApolloServerPluginLandingPageDisabled()

        // Option 2: Apollo Sandbox (cloud-hosted, safer)
        ApolloServerPluginLandingPageProductionDefault({
          graphRef: 'my-org/my-graph@production', // From Apollo Studio
          footer: false,
        })
      : // Development: local embedded Playground
        ApolloServerPluginLandingPageLocalDefault({
          embed: true,
          includeCookies: true, // Include auth cookies in requests
        }),
  ],
});

// Or: protect Playground route with middleware
app.use('/graphql', (req, res, next) => {
  // Only allow playground access from internal network
  const isInternalRequest =
    req.ip?.startsWith('10.') || req.ip?.startsWith('192.168.');
  const isApiRequest = req.method === 'POST';

  if (!isInternalRequest && !isApiRequest) {
    return res.status(403).send('Forbidden');
  }
  next();
});

