# Schema cho collaborative document editing
type Document {
  id: ID!
  title: String!
  content: String!         # Current content snapshot
  version: Int!            # Lamport clock / vector clock
  collaborators: [User!]!
  operations: [DocOperation!]!  # Operation history
}

type DocOperation {
  id: ID!
  type: OperationType!
  position: Int!
  content: String
  length: Int
  author: User!
  version: Int!
  timestamp: DateTime!
}

enum OperationType { INSERT DELETE RETAIN }

type Presence {
  userId: ID!
  user: User!
  documentId: ID!
  cursorPosition: Int!
  selectionStart: Int
  selectionEnd: Int
  lastSeen: DateTime!
}

type Mutation {
  # Apply text operation (OT-based)
  applyOperation(input: ApplyOperationInput!): ApplyOperationResult!
  # Update cursor/selection
  updatePresence(input: UpdatePresenceInput!): Presence!
}

type Subscription {
  # Real-time operation broadcast to other editors
  documentOperations(documentId: ID!): DocOperation!
  # Presence updates (cursor, selection)
  documentPresence(documentId: ID!): Presence!
}

---
// Server resolver — OT operation handling
const resolvers = {
  Mutation: {
    applyOperation: async (_, { input }, { db, pubsub, currentUser }) => {
      const { documentId, type, position, content, clientVersion } = input;

      // Optimistic locking + OT transform
      const doc = await db.documents.findById(documentId);

      // Transform operation against concurrent operations if needed
      const transformedOp = await transformOperation(
        { type, position, content },
        clientVersion,
        doc.version,
        await db.operations.getAfterVersion(documentId, clientVersion),
      );

      // Apply and persist
      const operation = await db.operations.create({
        ...transformedOp,
        documentId,
        authorId: currentUser.id,
        version: doc.version + 1,
      });

      // Broadcast to other subscribers
      await pubsub.publish(`DOC_OPS_${documentId}`, {
        documentOperations: operation,
      });

      return { operation, document: await db.documents.findById(documentId) };
    },
  },
  Subscription: {
    documentOperations: {
      subscribe: withFilter(
        (_, { documentId }) => pubsub.asyncIterator(`DOC_OPS_${documentId}`),
        // Filter out own operations
        (payload, _, context) =>
          payload.documentOperations.authorId !== context.currentUser.id,
      ),
    },
  },
};

